57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private final ClinicService clinicService;
65	
66	    private final OwnerMapper ownerMapper;
67	
68	    private final PetMapper petMapper;
69	
70	    private final VisitMapper visitMapper;
71	
72	    private final TelephoneNormalizer telephoneNormalizer;
73	
74	    public OwnerRestControllerV1(ClinicService clinicService,
75	                                 OwnerMapper ownerMapper,
76	                                 PetMapper petMapper,
77	                                 VisitMapper visitMapper,
78	                                 TelephoneNormalizer telephoneNormalizer) {
79	        this.clinicService = clinicService;
80	        this.ownerMapper = ownerMapper;
81	        this.petMapper = petMapper;
82	        this.visitMapper = visitMapper;
83	        this.telephoneNormalizer = telephoneNormalizer;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
114	        rejectBlankOwnerFields(ownerFieldsDto);
115	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
116	        if (!sharesHousehold) {
117	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
118	        }
119	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
120	        rejectDuplicateTelephone(normalizedTelephone);
121	        ownerFieldsDto.setTelephone(normalizedTelephone);
122	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
123	        HttpHeaders headers = new HttpHeaders();
124	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
125	        if (owner.getRegistrationDate() == null) {
126	            owner.setRegistrationDate(LocalDate.now());
127	        }
128	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
129	        if (sharesHousehold) {
130	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
131	        }
132	        this.clinicService.saveOwner(owner);
133	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
134	        headers.setLocation(UriComponentsBuilder.newInstance()
135	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
136	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
137	    }
138	
139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Override
141	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
142	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
143	        if (currentOwner == null) {
144	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
145	        }
146	        currentOwner.setAddress(ownerFieldsDto.getAddress());
147	        currentOwner.setCity(ownerFieldsDto.getCity());
148	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
149	        currentOwner.setLastName(ownerFieldsDto.getLastName());
150	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
151	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
152	        this.clinicService.saveOwner(currentOwner);
153	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Transactional
158	    @Override
159	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
160	        Owner owner = this.clinicService.findOwnerById(ownerId);
161	        if (owner == null) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        this.clinicService.deleteOwner(owner);
165	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Override
170	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
171	        Owner owner = this.clinicService.findOwnerById(ownerId);
172	        if (owner == null) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        HttpHeaders headers = new HttpHeaders();
176	        Pet pet = petMapper.toPet(petFieldsDto);
177	        owner.setId(ownerId);
178	        pet.setOwner(owner);
179	        pet.getType().setName(null);
180	        this.clinicService.savePet(pet);
181	        PetDto petDto = petMapper.toPetDto(pet);
182	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
183	            .buildAndExpand(pet.getId()).toUri());
184	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
190	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
191	        if (currentOwner != null) {
192	            Pet currentPet = this.clinicService.findPetById(petId);
193	            if (currentPet != null) {
194	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
195	                currentPet.setName(petFieldsDto.getName());
196	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
197	                this.clinicService.savePet(currentPet);
198	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
199	            }
200	        }
201	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
202	    }
203	
204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Override
206	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
207	        HttpHeaders headers = new HttpHeaders();
208	        Visit visit = visitMapper.toVisit(visitFieldsDto);
209	        Pet pet = new Pet();
210	        pet.setId(petId);
211	        visit.setPet(pet);
212	        this.clinicService.saveVisit(visit);
213	        VisitDto visitDto = visitMapper.toVisitDto(visit);
214	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
215	            .buildAndExpand(visit.getId()).toUri());
216	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
217	    }
218	
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
223	        Owner owner = this.clinicService.findOwnerById(ownerId);
224	        if (owner != null) {
225	            Pet pet = owner.getPet(petId);
226	            if (pet != null) {
227	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
228	            }
229	        }
230	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
231	    }
232	
233	    /**
234	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
235	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
236	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
237	     * blank (e.g. {@code "   "}). The offending field names are reported through an
238	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
239	     * as a 400 response carrying an {@code errors} array of field names.
240	     *
241	     * @param ownerFieldsDto the submitted owner fields
242	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
243	     */
244	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
245	        List<String> blankFields = new ArrayList<>();
246	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
247	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
248	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
249	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
250	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
251	        if (!blankFields.isEmpty()) {
252	            throw new InvalidOwnerFieldsException(blankFields);
253	        }
254	    }
255	
256	    private void addIfBlank(List<String> blankFields, String field, String value) {
257	        if (value != null && value.isBlank()) {
258	            blankFields.add(field);
259	        }
260	    }
261	
262	    /**
263	     * Normalizes an owner's optional email address. When present it is stored and returned
264	     * lower-cased (using {@link Locale#ROOT} so normalization is locale-independent). A missing
265	     * (null) email is left as-is. Syntactic validity is enforced by Bean Validation ({@code @Email}
266	     * on {@link OwnerFieldsDto}), so an invalid address is already rejected as a 400 before this
267	     * method runs.
268	     *
269	     * @param email the raw email value from the request, or {@code null} when omitted
270	     * @return the lower-cased email, or {@code null} when none was supplied
271	     */
272	    private String normalizeEmail(String email) {
273	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
274	    }
275	
276	    /**
277	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
278	     * {@code '<LAST3>-<NNNN>'}: {@code LAST3} is the upper-cased first three letters of the
279	     * owner's {@code lastName}, and {@code NNNN} is a global 4-digit zero-padded sequence equal
280	     * to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
281	     *
282	     * @param lastName the last name of the owner being created
283	     * @return the formatted customer code
284	     */
285	    private String nextCustomerCode(String lastName) {
286	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
287	        long sequence = this.clinicService.findAllOwners().size() + 1L;
288	        return String.format("%s-%04d", last3, sequence);
289	    }
290	
291	    /**
292	     * Rejects a create request whose normalized telephone is already used by any existing owner.
293	     * Existing owners' telephones are reduced to the same canonical form (via
294	     * {@link TelephoneNormalizer#canonicalize(String)}) before comparison, so numbers that differ
295	     * only in formatting still collide. A collision is reported through a
296	     * {@link DuplicateOwnerTelephoneException}, which the {@code ExceptionControllerAdvice} renders
297	     * as a 409 Conflict response.
298	     *
299	     * @param normalizedTelephone the canonical telephone of the owner being created
300	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
301	     */
302	    private void rejectDuplicateTelephone(String normalizedTelephone) {
303	        boolean duplicate = existingOwnerMatches(
304	            owner -> owner.getTelephone() == null ? null : telephoneNormalizer.canonicalize(owner.getTelephone()),
305	            normalizedTelephone);
306	        if (duplicate) {
307	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
308	        }
309	    }
310	
311	    /**
312	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
313	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null}
314	     * are ignored. The create endpoint's duplicate checks use this to reduce both an existing owner
315	     * and the owner being created to the same canonical key and reject a match.
316	     *
317	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
318	     * @param key the canonical key of the owner being created
319	     * @return {@code true} if some existing owner shares the key
320	     */
321	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
322	        return this.clinicService.findAllOwners().stream()
323	            .map(keyExtractor)
324	            .filter(Objects::nonNull)
325	            .anyMatch(key::equals);
326	    }
327	
328	    /**
329	     * Rejects a create request that shares a household with an existing owner: another owner already
330	     * has the same {@code lastName} and the same {@code address}. Both values are compared in
331	     * canonical form (case-insensitive with surrounding and internal whitespace collapsed to a single
332	     * space, see {@link #canonicalizeHousehold(String)}), so values that differ only in casing or
333	     * spacing still collide. A collision is reported through a {@link DuplicateOwnerHouseholdException},
334	     * which the {@code ExceptionControllerAdvice} renders as a 409 Conflict response. Callers skip this
335	     * check when the request opts in via {@code sharesHousehold}.
336	     *
337	     * @param lastName the last name of the owner being created
338	     * @param address the address of the owner being created
339	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household
340	     */
341	    private void rejectDuplicateHousehold(String lastName, String address) {
342	        String canonicalLastName = canonicalizeHousehold(lastName);
343	        String canonicalAddress = canonicalizeHousehold(address);
344	        if (canonicalLastName == null || canonicalAddress == null) {
345	            return;
346	        }
347	        boolean duplicate = this.clinicService.findAllOwners().stream()
348	            .anyMatch(owner -> canonicalLastName.equals(canonicalizeHousehold(owner.getLastName()))
349	                && canonicalAddress.equals(canonicalizeHousehold(owner.getAddress())));
350	        if (duplicate) {
351	            throw new DuplicateOwnerHouseholdException(canonicalLastName, canonicalAddress);
352	        }
353	    }
354	
355	    /**
356	     * Reduces a household field ({@code lastName} or {@code address}) to a canonical form for
357	     * case-insensitive, whitespace-insensitive comparison: leading and trailing whitespace is
358	     * trimmed, every run of internal whitespace is collapsed to a single space, and the result is
359	     * lower-cased using {@link java.util.Locale#ROOT} so comparison is locale-independent.
360	     *
361	     * @param value the raw field value, or {@code null}
362	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
363	     */
364	    private String canonicalizeHousehold(String value) {
365	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
366	    }
367	
368	    /**
369	     * Derives the stable, shared {@code householdId} for an owner joining a household via
370	     * {@code sharesHousehold}. The identifier is a deterministic function of the canonical
371	     * {@code lastName} and {@code address} (see {@link #canonicalizeHousehold(String)}), so every
372	     * owner with the same last name at the same address - regardless of casing or spacing - is
373	     * assigned the identical value. It is the first 16 upper-case hex characters of the SHA-256 hash
374	     * of the two canonical fields joined by a delimiter that cannot occur in the input.
375	     *
376	     * @param lastName the last name of the owner being created
377	     * @param address the address of the owner being created
378	     * @return the shared household identifier
379	     */
380	    private String householdId(String lastName, String address) {
381	        String key = canonicalizeHousehold(lastName) + "\n" + canonicalizeHousehold(address);
382	        try {
383	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
384	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
385	            StringBuilder sb = new StringBuilder(digest.length * 2);
386	            for (byte b : digest) {
387	                sb.append(String.format("%02X", b));
388	            }
389	            return sb.substring(0, 16);
390	        } catch (java.security.NoSuchAlgorithmException e) {
391	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
392	        }
393	    }
394	}
